{"command":"cd /testbed && timeout 20 python3 - <<'EOF'
from urllib.request import build_opener, ProxyHandler
for url in ['http://127.0.0.1:8766/v1/releases/checkout/readiness',
            'http://127.0.0.1:8765/reports']:
    try:
        with build_opener(ProxyHandler({})).open(url, timeout=10) as r:
            print(url, r.status, dict(r.headers))
            print(r.read().decode()[:2000])
    except Exception as e:
        print(url, 'ERR', repr(e))
        body = getattr(e, 'read', None)
        if body:
            try: print(body().decode()[:2000])
            except Exception: pass
    print('-'*60)
EOF"}
